# Trae check-in scheduled task entry point
# Generated by: node trae-checkin.mjs install
# ASCII only on purpose: Windows PowerShell 5.1 misreads UTF-8 without BOM.

$StoreDir = Join-Path $env:USERPROFILE '.trae-checkin'
$LogDir = Join-Path $StoreDir 'logs'
$LogFile = Join-Path $LogDir 'task.log'

if (-not (Test-Path $LogDir)) { New-Item -ItemType Directory -Path $LogDir -Force | Out-Null }

# Rotate task.log when it exceeds 1 MB
if (Test-Path $LogFile) {
    if ((Get-Item $LogFile).Length -gt 1MB) { Move-Item $LogFile "$LogFile.old" -Force }
}

# Prefer trae-checkin.mjs next to this script, fall back to install dir
$LocalScript = Join-Path $PSScriptRoot 'trae-checkin.mjs'
if (Test-Path $LocalScript) { $ScriptPath = $LocalScript } else { $ScriptPath = Join-Path $StoreDir 'trae-checkin.mjs' }

$Node = (Get-Command node -ErrorAction SilentlyContinue).Source
if (-not $Node) {
    "[$(Get-Date -Format s)] node not found, please install Node.js 18+ and add it to PATH" | Out-File -FilePath $LogFile -Append -Encoding ascii
    exit 1
}
if (-not (Test-Path $ScriptPath)) {
    "[$(Get-Date -Format s)] $ScriptPath not found, run: node trae-checkin.mjs install" | Out-File -FilePath $LogFile -Append -Encoding ascii
    exit 1
}

# Decode native output as UTF-8, otherwise Chinese messages become mojibake on GBK consoles
$Utf8 = New-Object System.Text.UTF8Encoding $false
[Console]::OutputEncoding = $Utf8
$OutputEncoding = $Utf8

$Output = & $Node $ScriptPath run 2>&1 | Out-String
$Code = $LASTEXITCODE

if ($Output -and $Output.Trim().Length -gt 0) {
    [System.IO.File]::AppendAllText($LogFile, $Output, $Utf8)
}
exit $Code
